// Loads the synthetic local credentials generated by infra/gen-local-secrets.mjs (never committed) and S3 helpers.
import { readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { CreateBucketCommand, HeadBucketCommand, ListMultipartUploadsCommand, ListObjectsV2Command, S3Client } from '@aws-sdk/client-s3';

const here = dirname(fileURLToPath(import.meta.url));
export const SECRETS_DIR = process.env.EVM011_SECRETS_DIR ?? resolve(here, '../../../../.scratch/EVM-011/secrets');
export const RESULTS_DIR = resolve(here, '../../../../.scratch/EVM-011/results');

export interface LocalConfig {
  accessKey: string;
  secretKey: string;
  token: string;
  bucket: string;
}

export function loadLocal(): LocalConfig {
  return JSON.parse(readFileSync(resolve(SECRETS_DIR, 'local.json'), 'utf8')) as LocalConfig;
}

export const S3_ENDPOINT = process.env.EVM011_S3_ENDPOINT ?? 'http://127.0.0.1:8333';

export function s3Client(cfg: LocalConfig, endpoint = S3_ENDPOINT): S3Client {
  return new S3Client({
    endpoint,
    region: 'us-east-1',
    forcePathStyle: true,
    credentials: { accessKeyId: cfg.accessKey, secretAccessKey: cfg.secretKey },
  });
}

export async function ensureBucket(s3: S3Client, bucket: string): Promise<void> {
  try {
    await s3.send(new HeadBucketCommand({ Bucket: bucket }));
  } catch {
    await s3.send(new CreateBucketCommand({ Bucket: bucket }));
  }
}

export interface DuplicateReport {
  objects: number;
  objectsWithoutAsset: string[];
  duplicateAssetIds: string[];
  orphanedMultipart: { key: string; uploadId: string }[];
}

/** (a) duplicate objects/assetIds, (b) orphaned multipart uploads. Re-PUTs of parts are counted by the engine (metric c). */
export async function countDuplicates(s3: S3Client, bucket: string): Promise<DuplicateReport> {
  const keys: string[] = [];
  let token: string | undefined;
  do {
    const r = await s3.send(new ListObjectsV2Command({ Bucket: bucket, Prefix: 'media/', ContinuationToken: token }));
    for (const o of r.Contents ?? []) keys.push(o.Key!);
    token = r.IsTruncated ? r.NextContinuationToken : undefined;
  } while (token);
  const seen = new Map<string, number>();
  const withoutAsset: string[] = [];
  for (const k of keys) {
    const m = /^media\/\d{4}\/\d{2}\/([0-9a-f-]{36})\/original$/.exec(k);
    if (!m) withoutAsset.push(k);
    else seen.set(m[1]!, (seen.get(m[1]!) ?? 0) + 1);
  }
  const mp = await s3.send(new ListMultipartUploadsCommand({ Bucket: bucket }));
  return {
    objects: keys.length,
    objectsWithoutAsset: withoutAsset,
    duplicateAssetIds: [...seen].filter(([, c]) => c > 1).map(([a]) => a),
    orphanedMultipart: (mp.Uploads ?? []).map((u) => ({ key: u.Key!, uploadId: u.UploadId! })),
  };
}
